#!/usr/bin/env node
// Builds the frontend from frontend/:
//   public/app.html  the page (frontend/app.template.html)
//   public/app.js    the app's script: frontend/src/**.js joined in the order listed in frontend/files.json
//   public/app.css   Tailwind
// The page loads app.js and app.css with ?v=<content hash>, so the server can let browsers keep them
// until the next deploy (a changed file gets a new URL).
//
// The src files are joined as-is, in order, into one classic script (not a module), so they share one
// global scope exactly as when it was a single inline script: every onclick="fn()" and every shared
// variable keeps working. It loads where the inline script was, at the end of <body>, without defer.
// Order matters for top-level `let`/`const` and code that runs at load; function declarations can
// live in any file.
//
//   node scripts/build-frontend.js           build once
//   node scripts/build-frontend.js --watch   rebuild on every save under frontend/ (local dev)
//
// The output is generated and committed (so deploys need no build). Don't edit it by hand: app.html and
// app.js carry a hash of their content, and the build refuses to overwrite one that no longer matches,
// so a hand edit is never silently lost.
//
// It also builds public/app.css with Tailwind 3.4.17 (frontend/tailwind.config.js) from the class names
// in the template and src/, and puts its version in the page's <link> (@@APP_CSS_VERSION@@) so a
// changed stylesheet is always fetched fresh. This replaced the in-browser Tailwind CDN script.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const FRONTEND = path.join(ROOT, 'frontend');
const TEMPLATE = path.join(FRONTEND, 'app.template.html');
const FILES = path.join(FRONTEND, 'files.json');
const OUT = path.join(ROOT, 'public', 'app.html');
const JS_OUT = path.join(ROOT, 'public', 'app.js');
const JS_VERSION = '@@APP_JS_VERSION@@';
// The note goes on the line after <!DOCTYPE html>: anything before the doctype risks old-style rendering.
const HEADER_RE = /\n<!-- GENERATED by scripts\/build-frontend\.js from frontend\/ \(edit those, not this file\)\. build:([0-9a-f]{12}) -->(?=\n)/;
const JS_HEADER_RE = /^\/\/ GENERATED by scripts\/build-frontend\.js from frontend\/src \(edit those, not this file\)\. build:([0-9a-f]{12})\n/;
const force = process.argv.includes('--force');
function handEdited(file, cur, m) {
    if (m && hash(cur.replace(m[0], '')) !== m[1] && !force) {
        throw new Error(`${file} was edited by hand since the last build. Move those edits into frontend/ `
            + `(compare with \`git diff ${file}\`), or rerun with --force to discard them.`);
    }
}

const hash = s => crypto.createHash('sha256').update(s).digest('hex').slice(0, 12);
// Always LF: git on Windows may check files out with CRLF, which must not look like a hand edit.
const lf = s => s.replace(/\r\n/g, '\n');

const CSS_OUT = path.join(ROOT, 'public', 'app.css');
const CSS_VERSION = '@@APP_CSS_VERSION@@';
function buildCss() {
    const css = execFileSync(process.execPath, [
        require.resolve('tailwindcss/lib/cli.js'),
        '-c', path.join(FRONTEND, 'tailwind.config.js'),
        '-i', path.join(FRONTEND, 'tailwind.input.css'),
        '--minify',
    ], { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 32 * 1024 * 1024 });
    if (!css.includes('--tw-')) throw new Error('Tailwind produced no CSS');
    const out = '/* GENERATED by scripts/build-frontend.js (Tailwind 3.4.17) from frontend/. Do not edit. */\n' + css.trim() + '\n';
    if (!fs.existsSync(CSS_OUT) || lf(fs.readFileSync(CSS_OUT, 'utf8')) !== out) fs.writeFileSync(CSS_OUT, out);
    return hash(out);
}

const MAP_OUT = path.join(ROOT, 'public', 'app.js.map');
// A source map from the joined script back to each src file, one mapping per line. esbuild reads it
// (as the input's inline map) and folds it into the map for the stripped output.
function lineMap(files) {
    const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    const vlq = n => { let v = n < 0 ? ((-n) << 1) | 1 : n << 1, s = ''; do { let d = v & 31; v >>>= 5; if (v) d |= 32; s += B64[d]; } while (v); return s; };
    const mappings = [], sources = [], sourcesContent = [];
    let prevSrc = 0, prevLine = 0;
    files.forEach((rel, si) => {
        const text = lf(fs.readFileSync(path.join(FRONTEND, 'src', rel), 'utf8'));
        sources.push('frontend/src/' + rel);
        sourcesContent.push(text);
        const lines = (text.endsWith('\n') ? text.slice(0, -1) : text).split('\n');
        lines.forEach((_, li) => { mappings.push(vlq(0) + vlq(si - prevSrc) + vlq(li - prevLine) + vlq(0)); prevSrc = si; prevLine = li; });
    });
    return { version: 3, sources, sourcesContent, names: [], mappings: mappings.join(';') };
}

function buildJs() {
    const files = JSON.parse(fs.readFileSync(FILES, 'utf8'));
    const seen = new Set();
    let script = '';
    for (const rel of files) {
        if (seen.has(rel)) throw new Error(`${rel} is listed twice in files.json`);
        seen.add(rel);
        const text = lf(fs.readFileSync(path.join(FRONTEND, 'src', rel), 'utf8'));
        script += text.endsWith('\n') ? text : text + '\n';
    }
    // A file in src/ that files.json doesn't list would silently never load.
    const onDisk = [];
    (function walk(dir, pre) {
        for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
            if (e.isDirectory()) walk(path.join(dir, e.name), pre + e.name + '/');
            else if (e.name.endsWith('.js')) onDisk.push(pre + e.name);
        }
    })(path.join(FRONTEND, 'src'), '');
    const unlisted = onDisk.filter(f => !seen.has(f));
    if (unlisted.length) throw new Error(`not in files.json (add them in load order): ${unlisted.join(', ')}`);

    // Shipped without comments and blank space (esbuild, whitespace only: no renaming, so function names
    // stay readable in errors and every global onclick target keeps its name). app.js.map maps it back
    // to frontend/src/<file>:<line> in the browser's developer tools. --readable skips the stripping.
    let code = script, map = null;
    if (!process.argv.includes('--readable')) {
        const r = require('esbuild').transformSync(script + '//# sourceMappingURL=data:application/json;base64,'
            + Buffer.from(JSON.stringify(lineMap(files))).toString('base64') + '\n',
            { loader: 'js', minifyWhitespace: true, legalComments: 'none', sourcemap: 'external', sourcefile: 'app.js' });
        code = r.code;
        map = JSON.parse(r.map);
        map.mappings = ';' + map.mappings; // the GENERATED line below sits above the code
    }
    const body = code + (map ? '//# sourceMappingURL=app.js.map\n' : '');
    const out = `// GENERATED by scripts/build-frontend.js from frontend/src (edit those, not this file). build:${hash(body)}\n` + body;
    const mapOut = map ? JSON.stringify(map) + '\n' : null;
    if (mapOut) { if (!fs.existsSync(MAP_OUT) || lf(fs.readFileSync(MAP_OUT, 'utf8')) !== mapOut) fs.writeFileSync(MAP_OUT, mapOut); }
    else if (fs.existsSync(MAP_OUT)) fs.unlinkSync(MAP_OUT);
    if (fs.existsSync(JS_OUT)) {
        const cur = lf(fs.readFileSync(JS_OUT, 'utf8'));
        handEdited('public/app.js', cur, cur.match(JS_HEADER_RE));
        if (cur !== out) fs.writeFileSync(JS_OUT, out);
    } else fs.writeFileSync(JS_OUT, out);
    return hash(out);
}

function build() {
    const cssVersion = buildCss();
    const jsVersion = buildJs();
    let body = lf(fs.readFileSync(TEMPLATE, 'utf8'));
    for (const [token, v] of [[CSS_VERSION, cssVersion], [JS_VERSION, jsVersion]]) {
        if (body.split(token).length !== 2) throw new Error(`${token} must appear exactly once in app.template.html`);
        body = body.replace(token, v);
    }
    const nl = body.indexOf('\n');
    const out = body.slice(0, nl) + `\n<!-- GENERATED by scripts/build-frontend.js from frontend/ (edit those, not this file). build:${hash(body)} -->` + body.slice(nl);

    if (fs.existsSync(OUT)) {
        const cur = lf(fs.readFileSync(OUT, 'utf8'));
        handEdited('public/app.html', cur, cur.match(HEADER_RE));
        if (cur === out) return false;
    }
    fs.writeFileSync(OUT, out);
    return true;
}

function run() {
    try {
        const changed = build();
        console.log(`[build-frontend] built (app.html ${changed ? 'changed' : 'unchanged'})  ${new Date().toLocaleTimeString()}`);
        return true;
    } catch (e) { console.error('[build-frontend] ' + e.message); return false; }
}

if (process.argv.includes('--watch')) {
    run();
    let t = null;
    fs.watch(FRONTEND, { recursive: true }, () => { clearTimeout(t); t = setTimeout(run, 100); });
    console.log('[build-frontend] watching frontend/ ...');
} else if (!run()) process.exit(1);
